from pathlib import Path
p=Path(__file__).resolve().parents[1]/'manuscript/Methods.md'
s=p.read_text(encoding='utf-8')
s=s.replace('Complete-reference water volume is compared with volume from every qualified native discharge interval, subject to the documented interval assumptions.', 'Complete-reference water volume is compared primarily with volume from all finite nonnegative observed native discharge values, including estimated or provisional values, subject to the documented interval assumptions. A separate denominator uses only quality-qualified discharge. Neither denominator represents unobserved runoff.')
s=s.replace('and a load functional \\(v_t\\) over 72 h beginning at assumed arrival, the score is', 'an assumed scoring delay \\(d_s\\), and a load functional \\(v_t\\) over 72 h beginning at assumed arrival and truncated at year end, the score is')
s=s.replace('R_t/\\lambda^d+', 'R_t/\\lambda^{d_s}+')
s=s.replace('Future discharge in \\(v_t\\) persists', 'Both \\(P^-\\) and \\(v_t\\) are constructed using \\(d_s\\); actual result availability still follows \\(a=s+d\\). Future discharge in \\(v_t\\) persists')
s=s.replace('An isolated candidate-information diagnostic uses fixed candidate times and fixed subsequent purchase calendars, comparing predictions with and without one additional sample; future reference values are used only to score the resulting load error.', 'An isolated candidate-information diagnostic uses development stations in 2023–2024, seed 41, and the budget-96 periodic calendar. The sole candidate in each month is the 15th at 12:00 UTC, without replacement. With real delay 24 h, we compare predictions with and without that additional sample during the 72 h after its arrival, keeping the subsequent purchase calendar and its saved innovation weights fixed. After the next successful scheduled return the two latest-residual trajectories coincide. Future reference values enter only the post-selection evaluation-eligibility screens (95% coverage and positive reference mass) and realized-error calculation. The added sample is not a competing policy at an equal budget.')
s+='\n\n## Computational assistance and verification\n\nOpenAI Codex and associated language-model agents assisted research design, source discovery, programming, debugging, analysis orchestration, figure scripting and substantive manuscript drafting. No language-model output supplied a measured concentration, an environmental observation or an empirical result. Numerical results came from archived observations and executable code; separate implementations checked chronology, budgets, units, event endpoints and aggregation. These computational checks do not substitute for the responsible authors’ scientific review and accountability. Figures were drawn deterministically from the recorded results, without generated visual data.\n'
p.write_text(s,encoding='utf-8')
